        (j,k),c=positive[0]
        assert abs(c)==1 and displacement=={(j,k):c,(k,j):-c}
        key=(i,j,k)
        assert key in basis and key not in seen
        seen.add(key)
    assert seen==basis
    return {'n':n,'rank':len(basis),'signed_permutation_verified':True}

